function updateProfileUI(){if(!profile)return;let n=profile.name||"Friend";$("#welcomeTitle").textContent=`${n}, welcome back.`;$("#greeting").textContent=(new Date().getHours()<12?"GOOD MORNING":new Date().getHours()<17?"GOOD AFTERNOON":"GOOD EVENING")+" / A MOMENT FOR YOU";$("#sideName").textContent=n;$("#sideAvatar").textContent=n[0].toUpperCase();$("#topName").textContent=n;$("#topInitial").textContent=n[0].toUpperCase();$("#profileAvatar").textContent=n[0].toUpperCase();$("#profileHeading").textContent=n;$("#profileEmailView").textContent=profile.email||"Your personal space";$("#todayDate").textContent=new Date().toLocaleDateString(undefined,{weekday:"long",month:"long",day:"numeric"});}
