function renderMoods(){let list=moods.filter(m=>selectedGroup==="all"||m[1]===selectedGroup);$("#moodGrid").innerHTML=list.map(m=>`<button class="mood-option ${selectedMood?.[0]===m[0]?"selected":""}" data-mood="${m[0]}"><span class="mood-glyph" style="background:${palette[m[1]]}">${glyph(m[4])}</span><span>${m[0]}</span></button>`).join("");$$("[data-mood]").forEach(b=>b.onclick=()=>{selectedMood=moods.find(m=>m[0]===b.dataset.mood);$("#moodDetail").classList.remove("hidden");$("#chosenMood").textContent=selectedMood[0];$("#chosenDesc").textContent=selectedMood[2];$("#saveMood").disabled=false;renderMoods()})}
