$("#saveMood").onclick=()=>{if(!selectedMood)return;entries.unshift({id:Date.now(),mood:selectedMood[0],group:selectedMood[1],description:selectedMood[2],intensity:+$("#intensity").value,triggers:[...triggers],note:$("#moodNote").value.trim(),date:new Date().toISOString()});write(ENTRIES,entries);renderNextStep(entries[0]);selectedMood=null;triggers=[];$("#moodNote").value="";$("#moodDetail").classList.add("hidden");$("#saveMood").disabled=true;$$("#triggerList button").forEach(x=>x.classList.remove("selected"));toast("Your check-in has been saved.");showPage("home")};
function renderNextStep(entry){const card=$("#nextStepCard");if(!card)return;const isToday=entry&&entry.date&&new Date(entry.date).toDateString()===new Date().toDateString();if(!isToday){card.classList.add("hidden");return}card.classList.remove("hidden");const heavy=["heavy","complex"].includes(entry.group);$("#nextStepTitle").textContent="You've checked in. What do you need now?";$("#nextStepText").textContent=heavy?"You don't have to solve the feeling. Choose a small way to meet yourself where you are.":"Let this moment be enough. If you'd like, choose a small way to carry it forward.";const choices=heavy?[{label:"Reflect",detail:"Put a few thoughts into words",page:"journal"},{label:"Find a word",detail:"Spend a moment with Scripture",href:"pages/bible.html"},{label:"Pause",detail:"Let the noise settle",href:"pages/ripple-room.html"}]:[{label:"Give thanks",detail:"Plant a small gratitude",page:"play",game:"garden"},{label:"Play",detail:"Take a mindful break",page:"play",game:"memory"},{label:"Reflect",detail:"Save a thought for today",page:"journal"}];$("#nextStepActions").innerHTML=choices.map(c=>`<button class="next-step-choice" ${c.href?`data-next-href="${c.href}\``:`data-next-page="${c.page}" ${c.game?`data-next-game="${c.game}\``:""}`}><strong>${c.label} ↗</strong><small>${c.detail}</small></button>`).join("");$$("[data-next-page]").forEach(b=>b.onclick=()=>{showPage(b.dataset.nextPage);if(b.dataset.nextGame){const gameButton=$(`[data-game="${b.dataset.nextGame}"]`);gameButton?.click()}});$$("[data-next-href]").forEach(b=>b.onclick=()=>location.href=b.dataset.nextHref)}
function renderHome(){updateProfileUI();renderNextStep(entries[0]);$("#statCount").textContent=entries.length;$("#statJournal").textContent=journal.length;$("#statMood").textContent=entries[0]?.mood||"—";$("#statMoodDate").textContent=entries[0]?dateLabel(entries[0].date):"Your latest reflection";$("#recentList").innerHTML=entries.slice(0,4).map(e=>`<div class="recent-item"><div class="mood-glyph" style="background:${palette[e.group]}">${moods.find(m=>m[0]===e.mood)?glyph(moods.find(m=>m[0]===e.mood)[4]):"◌"}</div><div><strong>${e.mood}</strong><small>${dateLabel(e.date)} · intensity ${e.intensity}/5</small></div></div>`).join("")||'<div class="empty">Your first check-in is waiting whenever you are.</div>';let quotes=["You can be a work in progress and still be worthy of gentleness.","You do not have to turn every feeling into a lesson.","Rest is a way of listening to yourself.","Some days, showing up softly is enough."];$("#dailyQuote").textContent=quotes[new Date().getDate()%quotes.length]}
function renderJournal(){ $("#journalCount").textContent=journal.length+" NOTES";$("#journalList").innerHTML=journal.map(j=>`<article class="journal-entry"><time>${dateLabel(j.date)}</time><p>${escapeHtml(j.text)}</p></article>`).join("")||'<div class="empty">Your pages will appear here.</div>';renderRevisit();}
function entryKey(e){return String(e.id??`${e.date||""}|${e.mood||""}|${e.note||""}`)}
function renderRevisit(){const moment=$("#revisitMoment"),composer=$("#revisitComposer");if(!moment||!composer)return;const candidates=entries.filter(e=>e&&e.date&&e.mood);if(!candidates.length){moment.innerHTML='<div class="empty">Once you have saved a mood check-in, you can return to it here.</div>';composer.classList.add("hidden");$("#revisitSaved").innerHTML='<div class="empty">Your revisit reflections will stay here.</div>';return;}if(!revisitEntry||!candidates.some(e=>entryKey(e)===entryKey(revisitEntry))){const today=new Date().toDateString();const older=candidates.filter(e=>new Date(e.date).toDateString()!==today);const pool=older.length?older:candidates;revisitEntry=pool[Math.floor(Math.random()*pool.length)];}moment.innerHTML=`<div class="revisit-card"><span class="revisit-date">${dateLabel(revisitEntry.date)}</span><h3>${escapeHtml(revisitEntry.mood)}</h3><p class="revisit-original">${escapeHtml(revisitEntry.note||revisitEntry.description||"You checked in with this feeling, even if you didn't leave a note.")}</p>${revisitEntry.triggers?.length?`<div class="revisit-tags">${revisitEntry.triggers.map(t=>`<span>${escapeHtml(t)}</span>`).join("")}</div>`:""}</div>`;composer.classList.remove("hidden");$("#revisitText").value="";const saved=revisits.filter(r=>r&&r.text).slice(0,5);$("#revisitSaved").innerHTML=saved.map(r=>`<article class="revisit-saved-item"><small>${dateLabel(r.savedAt)} · Looking back on ${dateLabel(r.entryDate)}</small><strong>${escapeHtml(r.mood||"A past moment")}</strong><p>${escapeHtml(r.text)}</p></article>`).join("")||'<div class="empty">Your revisit reflections will stay here.</div>';}
$("#anotherMoment").onclick=()=>{revisitEntry=null;renderRevisit()};
$("#saveRevisit").onclick=()=>{const text=$("#revisitText").value.trim();if(!text)return toast("Add a few words to your reflection first.");revisits.unshift({id:Date.now(),entryKey:entryKey(revisitEntry),entryDate:revisitEntry.date,mood:revisitEntry.mood,text,savedAt:new Date().toISOString()});write(REVISITS,revisits);toast("Your reflection has been saved.");renderRevisit()};
function escapeHtml(s){return String(s).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]))}
$("#saveJournal").onclick=()=>{let t=$("#journalText").value.trim();if(!t)return toast("Write a little something first.");journal.unshift({text:t,date:new Date().toISOString()});write(JOURNAL,journal);$("#journalText").value="";toast("Reflection saved.");renderJournal()};
const prompts=["What do you need more of right now?","What has been taking up space in your mind?","What is one thing you wish someone understood?","What felt lighter today, even for a moment?"];$("#journalPrompt").textContent=prompts[new Date().getDate()%prompts.length];
function renderInsights(){
  const total=entries.length;
  const intensityOf=e=>Number.isFinite(Number(e?.intensity))?Math.min(5,Math.max(1,Number(e.intensity))):3;
  const dated=entries.filter(e=>e?.date&&!Number.isNaN(new Date(e.date).getTime()));
  const avg=total?(entries.reduce((a,e)=>a+intensityOf(e),0)/total).toFixed(1):"—";
  $("#insightStats").innerHTML=`<article class="stat-card"><small>CHECK-INS MADE</small><strong>${total}</strong><p>Moments you paused</p></article><article class="stat-card"><small>JOURNAL PAGES</small><strong>${journal.length}</strong><p>Thoughts you kept</p></article><article class="stat-card"><small>AVERAGE INTENSITY</small><strong>${avg}</strong><p>Out of 5 · not a score</p></article>`;
  const now=new Date(),start=new Date(now);start.setHours(0,0,0,0);start.setDate(start.getDate()-6);
  const previousStart=new Date(start);previousStart.setDate(previousStart.getDate()-7);
  const inRange=(e,a,b)=>{const d=new Date(e.date);return d>=a&&d<=b};
  const recent=dated.filter(e=>inRange(e,start,now)),previous=dated.filter(e=>inRange(e,previousStart,new Date(start.getTime()-1)));
  let days=Array.from({length:7},(_,i)=>{let d=new Date(start);d.setDate(start.getDate()+i);return d});
  let counts=days.map(d=>recent.filter(e=>new Date(e.date).toDateString()===d.toDateString()).length),max=Math.max(1,...counts);
  $("#weekChart").innerHTML=days.map((d,i)=>`<div class="chart-col"><div class="chart-bar" style="height:${Math.max(5,counts[i]/max*100)}px" title="${counts[i]} check-ins"></div><small>${d.toLocaleDateString(undefined,{weekday:"short"}).slice(0,2)}</small></div>`).join("");
  const count={};recent.forEach(e=>{if(e?.mood)count[e.mood]=(count[e.mood]||0)+1});const sorted=Object.entries(count).sort((a,b)=>b[1]-a[1]);
  $("#emotionMix").innerHTML=sorted.slice(0,7).map(([m,n])=>`<div class="mix-row"><span>${escapeHtml(m)}</span><div class="mix-track"><div class="mix-fill" style="width:${n/Math.max(1,recent.length)*100}%"></div></div><b>${n}</b></div>`).join("")||'<div class="empty">Your emotion patterns will appear here after you add a check-in in the last seven days.</div>';
  const weeklyReflection=$("#weeklyReflection");
  if(!recent.length){weeklyReflection.innerHTML='No check-ins in the last seven days. Whenever you feel ready, add one and this space will begin reflecting your own entries. Your earlier check-ins are still saved in your history.'}
  else if(recent.length<3){weeklyReflection.innerHTML=`<p>You've made <strong>${recent.length} ${recent.length===1?'check-in':'check-ins'}</strong> in the last seven days. That's a beginning. A little more time and a few more entries may help you notice what tends to show up.</p><p>This is a snapshot of what you've recorded, not a measure of progress.</p>`}
  else {
    const top=sorted[0],avgRecent=(recent.reduce((a,e)=>a+intensityOf(e),0)/recent.length).toFixed(1);
    const triggerCounts={};recent.forEach(e=>(Array.isArray(e?.triggers)?e.triggers:[]).forEach(t=>triggerCounts[t]=(triggerCounts[t]||0)+1));
    const recurring=Object.entries(triggerCounts).filter(([,n])=>n>1).sort((a,b)=>b[1]-a[1]);
    let comparison='';
    if(previous.length>=3){const oldAvg=previous.reduce((a,e)=>a+intensityOf(e),0)/previous.length,newAvg=recent.reduce((a,e)=>a+intensityOf(e),0)/recent.length;const diff=Math.abs(newAvg-oldAvg).toFixed(1);comparison=diff<0.2?'Your average intensity is similar to the previous seven-day period.':newAvg<oldAvg?`Your average intensity is ${diff} points lower than the previous seven-day period.`:`Your average intensity is ${diff} points higher than the previous seven-day period.`;}
    const activeDays=counts.filter(n=>n>0).length;
    weeklyReflection.innerHTML=`<p>You've checked in <strong>${recent.length} times</strong> across <strong>${activeDays} of the last 7 days</strong>. <strong>${escapeHtml(top[0])}</strong> was the mood you recorded most often${top[1]>1?` (${top[1]} times)`:''}.</p><p>Your average intensity was <strong>${avgRecent}/5</strong>. ${comparison||'There is not yet enough earlier data for a week-to-week comparison.'}</p><p>${recurring.length?`<strong>${escapeHtml(recurring[0][0])}</strong> appeared as an influence in ${recurring[0][1]} check-ins${recurring.length>1?`, with ${escapeHtml(recurring[1][0])} appearing ${recurring[1][1]} times`:''}.`:'No influence has repeated yet in this seven-day snapshot; it is okay to leave that field blank.'}</p><p>These are patterns in what you've chosen to record. They don't explain why you feel a certain way, and they don't define you.</p>`;
  }
  const allTriggerCounts={};recent.forEach(e=>(Array.isArray(e?.triggers)?e.triggers:[]).forEach(t=>allTriggerCounts[t]=(allTriggerCounts[t]||0)+1));const triggerSorted=Object.entries(allTriggerCounts).sort((a,b)=>b[1]-a[1]);
  $("#triggerInsights").innerHTML=triggerSorted.slice(0,5).map(([t,n])=>`<div class="trigger-insight-row"><span>${escapeHtml(t)}</span><strong>${n} ${n===1?'entry':'entries'}</strong></div>`).join("")||'<div class="empty">Add an influence during check-in to see what tends to appear alongside your moods. You can leave this blank when you are unsure.</div>';
  $("#historyList").innerHTML=entries.map(e=>`<div class="history-row"><div class="mood-glyph" style="background:${palette[e.group]||'#e8e9f1'}">${glyph(moods.find(m=>m[0]===e.mood)?.[4]||"circle")}</div><div><strong>${escapeHtml(e.mood||'Mood')}</strong><small>${e.date?dateLabel(e.date):'Date unavailable'} · ${intensityOf(e)}/5</small></div><p>${escapeHtml(e.note||((Array.isArray(e.triggers)&&e.triggers.length)?e.triggers.join(", "):e.description||""))}</p></div>`).join("")||'<div class="empty">No check-ins yet.</div>';
}
function exportData(){let blob=new Blob([JSON.stringify({profile,entries,journal,garden,exportedAt:new Date().toISOString()},null,2)],{type:"application/json"}),url=URL.createObjectURL(blob),a=document.createElement("a");a.href=url;a.download="mood-deck-my-data.json";a.click();URL.revokeObjectURL(url);toast("Your data export is ready.")}
