function renderProfile(){if(!profile)return;$("#editName").value=profile.name;$("#editEmail").value=profile.email||""}
$("#editProfile").onsubmit=e=>{e.preventDefault();profile={...profile,name:$("#editName").value.trim()||profile.name,email:$("#editEmail").value.trim()};write(KEY,profile);updateProfileUI();toast("Profile updated.")};
$("#clearData").onclick=()=>showModal("Clear your reflections?","This removes your saved mood check-ins, journal pages and garden plants from this browser. Your profile will remain.",()=>{entries=[];journal=[];garden=[];write(ENTRIES,entries);write(JOURNAL,journal);write(GARDEN,garden);closeModal();renderProfile();toast("Your reflections have been cleared.")});
function showModal(title,body,action){$("#modalContent").innerHTML=`<p class="eyebrow">A QUICK CHECK</p><h3>${title}</h3><p>${body}</p><button class="btn danger" id="confirmAction">Yes, continue</button>`;$("#modal").classList.remove("hidden");$("#confirmAction").onclick=action}
function closeModal(){$("#modal").classList.add("hidden")}$("#closeModal").onclick=closeModal;
const responses=[["overwhelmed","That sounds like a lot to be holding at once. If you set everything else down for a moment, what feels most urgent inside you?"],["sad","I'm sorry it feels heavy right now. You don't need to rush past it. Would it help to name what you're missing, or would you rather simply sit with the feeling?"],["angry","It may be worth listening to what this anger is protecting. Did something feel unfair, crossed, or unheard?"],["anxious","Let's make this smaller. What is one thing you know for certain in this exact moment, separate from what might happen next?"],["happy","I love that there's some light here. What do you think made this moment feel good, and is there a way to make room for more of it?"],["lonely","That can be a difficult feeling to carry. Are you missing a particular person, or more the feeling of being understood and connected?"],["tired","Maybe your tiredness is asking for attention rather than another task. What kind of rest would actually help — physical, mental, emotional, or all three?"],["perspective","Let's look at it from another angle without dismissing how it feels. What part of the situation might you be seeing clearly, and what part is still uncertain?"],["reflect","Try this: what happened, what did you feel, and what might that feeling be asking you to notice?"]];function eloReply(text){let s=text.toLowerCase();let found=responses.find(([k])=>s.includes(k));return found?.[1]||"Thank you for putting that into words. What feels most important about it to you? You don't have to explain it perfectly — we can take it one piece at a time."}
function addBubble(text,who){let d=document.createElement("div");d.className="chat-bubble "+(who==="user"?"user-bubble":"elo-bubble");d.textContent=text;$("#chatMessages").append(d);$("#chatMessages").scrollTop=$("#chatMessages").scrollHeight}
function sendChat(text){if(!text.trim())return;addBubble(text,"user");$("#chatInput").value="";setTimeout(()=>addBubble(eloReply(text),"elo"),350)}
$("#chatForm").onsubmit=e=>{e.preventDefault();sendChat($("#chatInput").value)};$$(".suggestions button").forEach(b=>b.onclick=()=>sendChat(b.textContent));
$("#openBreath").onclick=()=>{let circle=$("#breathCircle"),label=$("#breathLabel"),phase=0;clearInterval(breathTimer);$("#openBreath").textContent="End breathing";$("#openBreath").onclick=()=>{clearInterval(breathTimer);circle.classList.remove("breathing");label.textContent="BREATHE";$("#openBreath").textContent="Begin breathing ↗";$("#openBreath").onclick=startBreath};function tick(){let steps=[["BREATHE IN",true],["HOLD",true],["BREATHE OUT",false],["REST",false]];let s=steps[phase%4];label.textContent=s[0];circle.classList.toggle("breathing",s[1]);phase++}function startBreath(){phase=0;tick();breathTimer=setInterval(tick,3500);$("#openBreath").textContent="End breathing";$("#openBreath").onclick=()=>{clearInterval(breathTimer);circle.classList.remove("breathing");label.textContent="BREATHE";$("#openBreath").textContent="Begin breathing ↗";$("#openBreath").onclick=startBreath}};startBreath()};
function stage(title,desc,content){let el=$("#gameStage");el.classList.remove("hidden");el.innerHTML=`<div class="panel-head"><div><p class="eyebrow">MOOD PLAY / TAKE YOUR TIME</p><h3>${title}</h3></div><button class="text-link" id="closeGame">Close ×</button></div><p class="muted">${desc}</p>${content}`;$("#closeGame").onclick=()=>el.classList.add("hidden");el.scrollIntoView({behavior:"smooth",block:"nearest"})}
const matches=[["You finally finish something you have been working towards.","Proud"],["Plans change at the last minute and you did not expect it.","Uncertain"],["Someone remembers a small detail that matters to you.","Loved"],["There are too many things asking for your attention.","Overwhelmed"],["You get a quiet moment with nothing to prove.","Calm"],["A friend cancels and you were looking forward to seeing them.","Disappointed"]];
function playMatch(){let q=matches[Math.floor(Math.random()*matches.length)];stage("Mood Match","Choose the emotion that might fit this moment. There can be more than one valid answer.",`<h3>${q[0]}</h3><div class="match-options">${["Proud","Uncertain","Loved","Overwhelmed","Calm","Disappointed"].sort(()=>Math.random()-.5).map(m=>`<button data-answer="${m}">${m}</button>`).join("")}</div><p id="matchFeedback" class="muted">No score here — just noticing how feelings connect to moments.</p><button class="btn light" id="nextMatch">Another moment ↗</button>`);$$("[data-answer]").forEach(b=>b.onclick=()=>{$("#matchFeedback").textContent=b.dataset.answer===q[1]?`That could fit. ${q[1]} is one way someone might feel here.`:`Interesting choice. ${b.dataset.answer} could be part of the picture too. The suggested match was ${q[1]}. Emotions are personal.`});$("#nextMatch").onclick=playMatch}
function playMemory(){let icons=["☀","♡","☁","✿","☾","✧","♧","〰"],deck=[...icons,...icons].sort(()=>Math.random()-.5);memoryState={deck,open:[],matched:[]};stage("Mindful Memory","Find the pairs. There is no timer — let your attention settle.",`<div class="memory-board">${deck.map((v,i)=>`<button class="memory-tile" data-card="${i}">✳</button>`).join("")}</div><p id="memoryStatus" class="muted">0 of 8 pairs found.</p>`);$$("[data-card]").forEach(b=>b.onclick=()=>{let i=+b.dataset.card;if(memoryState.matched.includes(i)||memoryState.open.includes(i)||memoryState.open.length===2)return;memoryState.open.push(i);b.textContent=deck[i];b.classList.add("revealed");if(memoryState.open.length===2){let [a,c]=memoryState.open;if(deck[a]===deck[c]){memoryState.matched.push(a,c);memoryState.open=[];$("#memoryStatus").textContent=`${memoryState.matched.length/2} of 8 pairs found.`;if(memoryState.matched.length===16)$("#memoryStatus").textContent="All pairs found. Take a breath and enjoy that little win."}else setTimeout(()=>{[a,c].forEach(n=>{let el=$(`[data-card="${n}"]`);if(el){el.textContent="✳";el.classList.remove("revealed")}});memoryState.open=[]},750)}})}
function playGarden(){stage("Gratitude Garden","Plant a small thought about something you appreciate. Tiny things count.",`<form class="garden-form" id="gardenForm"><input id="gardenInput" maxlength="120" placeholder="Today, I'm grateful for…"><button class="btn primary">Plant it</button></form><div class="garden-plants">${garden.map(x=>`<span class="plant" title="${escapeHtml(x)}">✿</span>`).join("")}</div><p class="tiny">${garden.length} little ${garden.length===1?"seed":"seeds"} planted.</p>`);$("#gardenForm").onsubmit=e=>{e.preventDefault();let v=$("#gardenInput").value.trim();if(!v)return;garden.unshift(v);write(GARDEN,garden);playGarden();toast("A little gratitude has been planted.")}}
function playZen(){stage("Zen Pause","A tiny grounding practice. Move through each step gently.",`<h3>Notice your surroundings.</h3><div class="zen-steps"><span>5 things you can see</span><span>4 things you can feel</span><span>3 things you can hear</span><span>2 things you can smell</span><span>1 thing you can taste</span></div><p class="muted">Take your time. You can stop whenever you need to.</p>`)}
$$("[data-game]").forEach(b=>b.onclick=()=>({match:playMatch,memory:playMemory,garden:playGarden,zen:playZen}[b.dataset.game])());
function boot(){if(profile){$("#splash").classList.add("out");setTimeout(()=>$("#splash").remove(),650);$("#app").classList.remove("hidden");updateProfileUI();showPage("home")}else{setTimeout(()=>{$("#splash").classList.add("out");setTimeout(()=>{$("#splash").remove();$("#auth").classList.remove("hidden")},550)},1300)}}
renderMoods();boot();